-- GATE: G15 ZERO
SELECT (SELECT count(*) FROM dim_proveedor) - (SELECT count(*) FROM tmp_a_proveedores) AS dif_dim_proveedor, (SELECT count(*) FROM dim_producto) - (SELECT count(*) FROM tmp_a_productos) AS dif_dim_producto, (SELECT count(*) FROM dim_contacto_proveedor) - (SELECT count(*) FROM tmp_a_contacto_proveedor) AS dif_dim_contacto_proveedor, (SELECT count(*) FROM puente_proveedor_categoria_proveedor) - (SELECT count(*) FROM tmp_a_proveedor_categoria_proveedor) AS dif_puente_proveedor_categoria_proveedor, (SELECT count(*) FROM puente_proveedor_categoria_producto) - (SELECT count(*) FROM tmp_a_proveedor_categoria_producto) AS dif_puente_proveedor_categoria_producto, (SELECT count(*) FROM puente_proveedor_producto) - (SELECT count(*) FROM tmp_a_proveedor_x_producto) AS dif_puente_proveedor_producto, (SELECT count(*) FROM dim_categoria) - (SELECT count(*) FROM tmp_a_categorias) AS dif_dim_categoria, (SELECT count(*) FROM dim_categoria_proveedor) - (SELECT count(*) FROM tmp_a_categorias_proveedor) AS dif_dim_categoria_proveedor, (SELECT count(*) FROM dim_unidad_organizacional) - (SELECT count(*) FROM tmp_a_unidades_organizacionales) AS dif_dim_unidad_organizacional, (SELECT count(*) FROM categoria_proveedor_x_categoria_producto) - (SELECT count(*) FROM tmp_a_categoria_proveedor_x_categoria_producto) AS dif_categoria_proveedor_x_categoria_producto, (SELECT count(*) FROM dim_tiempo) - (SELECT count(*) FROM tmp_a_tiempo) AS dif_dim_tiempo, (SELECT count(*) FROM hechos_compras) - (SELECT count(*) FROM tmp_a_hechos) AS dif_hechos_compras, CASE WHEN abs(coalesce((SELECT sum(monto_total) FROM hechos_compras), 0) - coalesce((SELECT sum(monto_total) FROM tmp_a_hechos), 0)) > 0.01 THEN 1 ELSE 0 END AS dif_monto_total;
